{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_22",
      "quote": "Additionally, previous clinical practice guidelines on the management of type 2 diabetes mellitus, including those from the American Diabetes Association 58 and the American Association of Clinical Endocrinology/American College of Endocrinology, 59 recommend the use of prognostic models developed and validated in non-­ diabetic populations, such as the Pooled Cohort Equation and the FHS. Our findings may enable the adoption of diabetes specific prognostic models in the development of future clinical practice guidelines for diabetes management.",
      "reason": "The text describes the current state of knowledge regarding existing guidelines and the reliance on non-diabetes-specific models, highlighting the uncertainty/gap regarding the use of diabetes-specific models."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_22",
      "quote": "Models identified by our systematic review, such as RECODe, should help the development and updating of clinical practice guidelines, health technology assessments, and subsequently clinicians, patients, policy makers and payers in informing individual decision making. These models enable appropriate risk stratification for patients with type 2 diabetes mellitus, enable identification of risk stratified baseline risks (ie, likelihood of events occurring without treatment) across patient important outcomes, and facilitate estimation of risk stratified absolute effect estimates for treatments",
      "reason": "The text explains the importance and need for the review by detailing how the identified models can improve clinical practice, guideline development, and patient decision-making."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_27",
      "quote": "14 Buchan TA, Malik A, Chan C, et al . Predictive models for cardiovascular and kidney outcomes in patients with type 2 diabetes: systematic review and meta-­ analyses. Heart 2021;107:1962-73.",
      "reason": "The manuscript cites a previous systematic review (Buchan et al., 2021) in the reference list, and the text discusses the need for this updated review in the context of linked living guidelines and the need for ongoing evidence synthesis (as described in text_10)."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a systematic review of prognostic models, not a review of intervention effects; therefore, a mechanism of action is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a systematic review of prognostic models, not a complex intervention, so a logic model is not required."
    }
  ],
  "confidence": 95
}

