{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Studies validating prognostic models that predicted all cause and cardiovascular mortality, admission to hospital for heart failure, kidney failure, myocardial infarction, or ischaemic stroke in adults with type 2 diabetes mellitus, including people with established cardiovascular disease or chronic kidney disease, or both. Risk models evaluating composite outcomes were not eligible.",
      "reason": "The manuscript specifies the population (adults with type 2 diabetes mellitus, including those with CVD/CKD), the intervention/exposure (prognostic models), and the outcomes (mortality, heart failure, etc.) used to determine eligibility."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not report eligibility criteria regarding report characteristics such as dissemination year, language, or publication status."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "There is no evidence that the review excluded studies based on the distinction between outcomes not being measured versus outcomes not being reported; rather, the text indicates that data were extracted from figures when not reported in text."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "For each model and outcome, using a random effects model, the reported discrimination measures were pooled, reported as c statistics.",
      "reason": "The manuscript specifies that studies were grouped by model and outcome for synthesis, and further mentions subgroup analyses by risk of bias in chunk text_8."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_22",
      "quote": "Fourthly, our review excluded prognostic models solely evaluating composite outcomes, such as major adverse cardiovascular events, as our linked guideline focused on individual cardiovascular and kidney outcomes.",
      "reason": "The manuscript provides a clear rationale for the restriction on composite outcomes."
    }
  ],
  "confidence": 100
}

